source_context:
  1: ---
  2: - hosts: localhost # noqa name[play]
  3:   module_defaults:
  4:     ansible.builtin.setup:
  5:       fact_path: "/srv/git/saltbox/ansible_facts.d"
  6:   vars_files:
  7:     - ['accounts.yml', 'defaults/accounts.yml.default']
  8:     - ['settings.yml', 'defaults/settings.yml.default']
  9:     - ['adv_settings.yml', 'defaults/adv_settings.yml.default']
 10:     - ['backup_config.yml', 'defaults/backup_config.yml.default']
 11:     - ['providers.yml', 'defaults/providers.yml.default']
 12:     - ['hetzner_vlan.yml', 'defaults/hetzner_vlan.yml.default']
 13:   roles:
 14:     - { role: user_check, tags: ['always'] }
 15:     - { role: pre_tasks, tags: ['always', 'pre-tasks'] }
 16:     - { role: sanity_check, tags: ['always', 'sanity-check'] }
 17:     - { role: backup, tags: ['backup'] }
 18:     - { role: backup2, tags: ['backup2'] }
 19:     - { role: restore, tags: ['restore'] }
 20:     # Core
 21:     - { role: kernel, tags: ['core', 'saltbox', 'mediabox', 'feederbox', 'preinstall', 'kernel'] }
 22:     - { role: hetzner, tags: ['core', 'saltbox', 'mediabox', 'feederbox', 'preinstall', 'hetzner'] }
 23:     - { role: user, tags: ['core', 'saltbox', 'mediabox', 'feederbox', 'preinstall', 'user'] }
 24:     - { role: shell, tags: ['core', 'saltbox', 'mediabox', 'feederbox', 'preinstall', 'shell'] }
 25:     - { role: rclone, tags: ['core', 'saltbox', 'mediabox', 'feederbox', 'preinstall', 'rclone'] }
 26:     - { role: mount_templates, tags: ['core', 'saltbox', 'mediabox', 'feederbox', 'preinstall', 'mounts', 'mount-templates'] }
 27:     - { role: system, tags: ['core', 'saltbox', 'mediabox', 'feederbox', 'system'] }
 28:     - { role: common, tags: ['core', 'saltbox', 'mediabox', 'feederbox', 'common'] }
 29:     - { role: motd, tags: ['core', 'saltbox', 'mediabox', 'feederbox', 'motd', 'motd-generate-config'], when: ['use_motd'] }
 30:     - { role: remote, tags: ['core', 'saltbox', 'mediabox', 'feederbox', 'mounts'] }
 31:     - { role: unionfs, tags: ['core', 'saltbox', 'mediabox', 'feederbox', 'mounts'] }
 32:     - { role: nvidia, tags: ['core', 'saltbox', 'mediabox', 'feederbox', 'docker', 'nvidia', 'nvidia-purge'], when: ['use_nvidia or ("nvidia-purge" in ansible_run_tags)'] }
 33:     - { role: docker, tags: ['core', 'saltbox', 'mediabox', 'feederbox', 'docker', 'docker-filesystem-resize'] }
 34:     - { role: scripts, tags: ['core', 'saltbox', 'mediabox', 'feederbox', 'scripts'] }
 35:     - { role: sandbox, tags: ['core', 'saltbox', 'mediabox', 'feederbox', 'sandbox'] }
 36:     - { role: crowdsec, tags: ['core', 'saltbox', 'mediabox', 'feederbox', 'crowdsec'], when: ['crowdsec_is_enabled'] }
 37:     - { role: traefik, tags: ['core', 'saltbox', 'mediabox', 'feederbox', 'traefik', 'traefik-reset-certs'] }
 38:     - { role: cloudflare, tags: ['core', 'saltbox', 'mediabox', 'feederbox', 'cloudflare'], when: ['cloudflare_is_enabled'] }
 39:     - { role: main_tags, tags: ['saltbox', 'mediabox', 'feederbox'] }
 40:     # Apps Start
 41:     - { role: media_server, tags: ['media-server'] }
 42:     - { role: download_clients, tags: ['download-clients'] }
 43:     - { role: download_indexers, tags: ['download-indexers'] }
 44:     - { role: tautulli, tags: ['tautulli'] }
 45:     - { role: seerr, tags: ['seerr'] }
 46:     - { role: portainer, tags: ['portainer'] }
 47:     - { role: organizr, tags: ['organizr'] }
 48:     - { role: cloudplow, tags: ['saltbox', 'feederbox', 'cloudplow', 'cloudplow-reset'], when: ['use_cloudplow'] }
 49:     - { role: cloudplow_disable, tags: ['cloudplow-disable']}
 50:     - { role: sonarr, tags: ['sonarr'] }
 51:     - { role: radarr, tags: ['radarr'] }
 52:     - { role: lidarr, tags: ['lidarr'] }
 53:     - { role: iperf3, tags: ['iperf3'] }
 54:     - { role: glances, tags: ['glances'] }
 55:     - { role: btop, tags: ['btop'] }
 56:     - { role: asshama, tags: ['asshama'] }
 57:     - { role: arr_db, tags: ['arr-db'] }
 58:     - { role: authelia, tags: ['authelia', 'authelia-reset', 'lldap-reset'] }
 59:     - { role: authentik, tags: ['authentik', 'authentik-reset'] }
 60:     - { role: autobrr, tags: ['autobrr'] }
 61:     - { role: autoheal, tags: ['autoheal'] }
 62:     - { role: autoplow, tags: ['autoplow'] }
 63:     - { role: autoscan, tags: ['autoscan'] }
 64:     - { role: bazarr, tags: ['bazarr'] }
 65:     - { role: btrfsmaintenance, tags: ['btrfsmaintenance'] }
 66:     - { role: cadvisor, tags: ['cadvisor'] }
 67:     - { role: ddclient, tags: ['ddclient'] }
 68:     - { role: ddns, tags: ['ddns'] }
 69:     - { role: deluge, tags: ['deluge'] }
 70:     - { role: diun, tags: ['diun'] }
 71:     - { role: docker_socket_proxy, tags: ['docker-socket-proxy'] }
 72:     - { role: dozzle, tags: ['dozzle'] }
 73:     - { role: emby, tags: ['emby'] }
 74:     - { role: gluetun, tags: ['gluetun'] }
 75:     - { role: grafana, tags: ['grafana'] }
 76:     - { role: jackett, tags: ['jackett'] }
 77:     - { role: jellyfin, tags: ['jellyfin'] }
 78:     - { role: mainline, tags: ['mainline'] }
 79:     - { role: mariadb, tags: ['mariadb'] }
 80:     - { role: mongodb, tags: ['mongodb'] }
 81:     - { role: netdata, tags: ['netdata'] }
 82:     - { role: nginx, tags: ['nginx'] }
 83:     - { role: node_exporter, tags: ['node-exporter'] }
 84:     - { role: nzbget, tags: ['nzbget'] }
 85:     - { role: nzbhydra2, tags: ['nzbhydra2'] }
 86:     - { role: nzbthrottle, tags: ['nzbthrottle'] }
 87:     - { role: overseerr, tags: ['overseerr'] }
 88:     - { role: petio, tags: ['petio'] }
 89:     - { role: plex, tags: ['plex', 'plex-reset-codecs', 'plex-reclaim'] }
 90:     - { role: plex_db, tags: ['plex-db'] }
 91:     - { role: postgres, tags: ['postgres'] }
 92:     - { role: postgres_host, tags: ['postgres-host'] }
 93:     - { role: prometheus, tags: ['prometheus'] }
 94:     - { role: prowlarr, tags: ['prowlarr'] }
 95:     - { role: python, tags: ['python'] }
 96:     - { role: qbittorrent, tags: ['qbittorrent'] }
 97:     - { role: redis, tags: ['redis'] }
 98:     - { role: sabnzbd, tags: ['sabnzbd'] }
 99:     - { role: scrutiny, tags: ['scrutiny'] }
100:     - { role: transfer, tags: ['transfer'] }
101:     - { role: unpackerr, tags: ['unpackerr'] }
102:     - { role: whisparr, tags: ['whisparr'] }
103:     - { role: yyq, tags: ['yyq'] }
104:     # Apps End
105:     - { role: custom, tags: ['custom'] }
106:     - { role: diag, tags: ['diag'] }
107:     - { role: authentik_worker, tags: ['never'] }
108:     - { role: error_pages, tags: ['never'] }
109:     - { role: lldap, tags: ['never'] }
110:     - { role: hetzner_vlan, tags: ['hetzner-vlan-deploy', 'hetzner-vlan-remove'] }
111:     - { role: permissions, tags: ['fix-permissions'] }
112:     - { role: plex_auth_token, tags: ['plex-auth-token'] }
113:     - { role: plex_fix_futures, tags: ['plex-fix-futures'] }
114:     - { role: saltbox_mod, tags: ['saltbox-mod'] }
115:     - { role: traefik_file_template, tags: ['generate-traefik-file-template'] }
116:     - { role: traefik_template, tags: ['generate-traefik-template'] }
117:     # Reboot checker
118:     - { role: reboot, tags: ['core', 'saltbox', 'mediabox', 'feederbox', 'system'] }
